#![cfg_attr(any(), verified(opt_out = "gui_tool"))]

use eframe::egui;

/// Declares a [`crate::framework::SimulationFramework`]-backed [`ExplorerTab`] struct and forwards
/// standard lifecycle, state persistence, focus, and framework inspection methods using the
/// module-scoped `EXPLORER_DOMAIN` and `EXPLORER_SLUG` constants generated by `build.rs` from
/// `// @explorer_domain = "..."` and `// @explorer_slug = "..."`.
#[macro_export]
macro_rules! declare_simulation_tab {
    (
        $(#[$meta:meta])*
        $vis:vis struct $tab_ty:ident,
        $display_name:expr $(,)?
    ) => {
        $(#[$meta])*
        /// Auto-discovered simulation tab backed by [`crate::framework::SimulationFramework`].
        $vis struct $tab_ty {
            /// Underlying simulation framework managing tools, presets, theory portal, and exports.
            pub framework: $crate::framework::SimulationFramework,
        }

        impl Default for $tab_ty {
            fn default() -> Self {
                Self {
                    framework: $crate::framework::SimulationFramework::new(EXPLORER_SLUG),
                }
            }
        }

        impl $crate::tabs::ExplorerTab for $tab_ty {
            fn name(&self) -> &'static str {
                $display_name
            }

            fn academic_domain(&self) -> &'static str {
                EXPLORER_DOMAIN
            }

            fn url_slug(&self) -> &'static str {
                EXPLORER_SLUG
            }

            fn show_inside(&mut self, ui: &mut eframe::egui::Ui, _frame: &mut eframe::Frame) {
                self.framework.show_inside(ui, EXPLORER_SLUG);
            }

            fn state_revision(&self) -> u64 {
                self.framework.state_revision()
            }

            fn save_state(&self) -> Option<String> {
                self.framework.save_state()
            }

            fn load_state(&mut self, state: &str) {
                self.framework.load_state(state);
            }

            fn focused_canvas_id(&self) -> Option<eframe::egui::Id> {
                self.framework.focused_canvas_id()
            }

            fn select_tool_by_name(&mut self, name: &str) -> bool {
                self.framework.select_tool_by_name(name)
            }

            fn framework(&self) -> Option<&$crate::framework::SimulationFramework> {
                Some(&self.framework)
            }

            fn framework_mut(&mut self) -> Option<&mut $crate::framework::SimulationFramework> {
                Some(&mut self.framework)
            }
        }
    };
}

include!(concat!(env!("OUT_DIR"), "/generated_tabs.rs"));

/// A trait for defining a tab in the Math Explorer application.
///
/// This trait serves as the primary extension point for the GUI. Each mathematical domain
/// (e.g., MRI Physics, Game Theory) implements this trait either via [`crate::declare_simulation_tab!`]
/// or as a custom struct in `src/tabs/`.
///
/// # Automated Plugin Discovery
///
/// `math_explorer_gui/build.rs` scans `src/tabs/` at compile time for `declare_simulation_tab!`
/// invocations and `impl ExplorerTab for YourStruct` blocks, generating module wrappers and
/// instantiation builders without manual registration in `app/` or `tabs/mod.rs`.
///
/// ## Configuration Directives
///
/// Every tab module in `src/tabs/` declares its academic domain and canonical URL slug at the top
/// of the file, along with optional Cargo feature and ordering directives:
///
/// - `// @explorer_domain = "Pure Math"`: Academic domain category for top navigation bar grouping.
/// - `// @explorer_slug = "my_tab"`: Unique canonical `#tab=<slug>` identifier (validated by `build.rs`).
/// - `// @explorer_feature = "feature_name"`: Optional Cargo feature gate for conditional compilation.
/// - `// @explorer_order = 10`: Optional navigation sort order (lower numbers appear first; default `100`).
///
/// # Example
///
/// ```rust,no_run
/// // @explorer_feature = "pure_math"
/// // @explorer_domain = "Pure Math"
/// // @explorer_slug = "my_tab"
/// // @explorer_order = 1
///
/// use math_explorer_gui::tabs::ExplorerTab;
/// use eframe::egui;
///
/// #[derive(Default)]
/// pub struct MyTab {
///     counter: i32,
/// }
///
/// impl ExplorerTab for MyTab {
///     fn name(&self) -> &'static str {
///         "My Tab"
///     }
///
///     fn academic_domain(&self) -> &'static str {
///         "Pure Math"
///     }
///
///     fn url_slug(&self) -> &'static str {
///         "my_tab"
///     }
///
///     fn show_inside(&mut self, ui: &mut egui::Ui, _frame: &mut eframe::Frame) {
///         egui::CentralPanel::default().show_inside(ui, |ui| {
///             ui.heading("My Tab");
///             if ui.button("Increment").clicked() {
///                 self.counter += 1;
///             }
///             ui.label(format!("Count: {}", self.counter));
///         });
///     }
/// }
/// ```
pub trait ExplorerTab {
    /// Returns the name of the tab, displayed in the navigation bar.
    fn name(&self) -> &'static str;

    /// Academic domain category of the tab for top navigation bar grouping.
    fn academic_domain(&self) -> &'static str;

    /// Canonical URL slug identifying this tab in `#tab=<slug>` share links.
    fn url_slug(&self) -> &'static str;

    /// Renders the content of the tab inside a scoped parent `egui::Ui` (such as a multi-pane viewport region).
    fn show_inside(&mut self, ui: &mut egui::Ui, frame: &mut eframe::Frame);

    /// Monotonic or deterministic revision token for persisted tab state (`0` if untracked).
    fn state_revision(&self) -> u64 {
        0
    }

    /// Serializes the tab's parameter and panel state into a String.
    fn save_state(&self) -> Option<String> {
        None
    }

    /// Deserializes and restores the tab's parameter and panel state from a String.
    fn load_state(&mut self, _state: &str) {}

    /// Returns the active tool's interactive canvas `Id` when focus is owned by a non-text canvas.
    fn focused_canvas_id(&self) -> Option<egui::Id> {
        None
    }

    /// Activates a tool within this tab by name.
    /// Returns true if a matching tool was found and activated.
    fn select_tool_by_name(&mut self, _name: &str) -> bool {
        false
    }

    /// Returns a reference to the underlying [`crate::framework::SimulationFramework`] when backed by one.
    fn framework(&self) -> Option<&crate::framework::SimulationFramework> {
        None
    }

    /// Returns a mutable reference to the underlying [`crate::framework::SimulationFramework`] when backed by one.
    fn framework_mut(&mut self) -> Option<&mut crate::framework::SimulationFramework> {
        None
    }

    /// Applies the root-hoisted `StarterGallery` modal outcome to this tab instance.
    fn apply_starter_gallery_outcome(
        &mut self,
        ctx: &egui::Context,
        id_source: &str,
        is_open: bool,
        selected: Option<crate::starter_gallery::StarterCard>,
    ) {
        if let Some(fw) = self.framework_mut() {
            fw.apply_starter_gallery_outcome(ctx, id_source, is_open, selected);
        }
    }

    /// Applies either a starter card or inverse challenge selection from `StarterGallery`.
    fn apply_starter_gallery_selection(
        &mut self,
        ctx: &egui::Context,
        id_source: &str,
        is_open: bool,
        selected: Option<crate::starter_gallery::GallerySelection>,
    ) {
        match selected {
            Some(crate::starter_gallery::GallerySelection::Starter(card)) => {
                self.apply_starter_gallery_outcome(ctx, id_source, is_open, Some(card));
            }
            other => {
                if let Some(fw) = self.framework_mut() {
                    fw.apply_starter_gallery_selection(ctx, id_source, is_open, other);
                }
            }
        }
    }

    /// Active `InteractiveTool` identifier for `#tool=<id>` share links (`None` for single-view tabs).
    fn active_tool_id(&self) -> Option<&'static str> {
        self.framework().and_then(|fw| fw.active_tool_id())
    }

    /// Deterministic parameter-only revision token for 300 ms debounced URL sync.
    fn url_state_revision(&self) -> u64 {
        self.framework()
            .map_or_else(|| self.state_revision(), |fw| fw.url_state_revision())
    }

    /// Exports active simulation parameters as a compact `PresetWrapper` JSON envelope for URL sharing.
    fn export_url_preset_json(&self) -> Result<Option<String>, String> {
        match self.framework() {
            Some(fw) => fw.export_url_preset_json(),
            None => Ok(None),
        }
    }

    /// Encodes a `#tab=<slug>...` URL fragment for this tab (including active story or challenge IDs when present).
    fn encode_url_share_fragment(&self) -> Result<String, String> {
        if let Some(fw) = self.framework() {
            return fw.encode_share_fragment_for_tab(self.url_slug());
        }
        let preset_json = self.export_url_preset_json()?;
        crate::url_state::encode_share_fragment(
            self.url_slug(),
            self.active_tool_id(),
            preset_json.as_deref(),
        )
    }

    /// Validates and applies `ShareUrlParams` (supporting `&preset=`, `&challenge=`, `&step=`, and `&state=`).
    fn import_url_share_params(
        &mut self,
        params: &crate::url_state::ShareUrlParams,
        ctx: Option<&egui::Context>,
    ) -> Result<(), String> {
        if params.preset.is_none() && params.challenge.is_none() {
            return self
                .import_url_preset_json(params.tool.as_deref(), params.state_json.as_deref());
        }
        if let Some(fw) = self.framework_mut() {
            return fw.import_url_share_params(params, ctx);
        }
        Err(format!(
            "Tab '{}' does not support story presets or challenges",
            self.name()
        ))
    }

    /// Validates and applies a shared URL tool identifier and `PresetWrapper` JSON payload.
    fn import_url_preset_json(
        &mut self,
        tool_id: Option<&str>,
        preset_json: Option<&str>,
    ) -> Result<(), String> {
        if let Some(fw) = self.framework_mut() {
            return fw.import_url_preset_json(tool_id, preset_json);
        }
        if let Some(unexpected_tool) = tool_id {
            return Err(format!(
                "Tab '{}' does not support sub-tool '{unexpected_tool}'",
                self.name()
            ));
        }
        if preset_json.is_some() {
            return Err(format!(
                "URL parameter state import is not supported for '{}'",
                self.name()
            ));
        }
        Ok(())
    }
}

#[cfg(all(test, not(target_arch = "wasm32")))]
mod tests {
    use std::collections::HashSet;
    use std::fs;
    use std::path::{Path, PathBuf};
    use std::process::Command;
    use std::thread;
    use std::time::Duration;

    fn read_build_script_output(out_dir: &Path) -> String {
        let parent_dir = out_dir
            .parent()
            .expect("OUT_DIR must have a parent build directory");
        let build_output_path = [
            parent_dir.join("output"),
            parent_dir.join("run").join("stdout"),
        ]
        .into_iter()
        .find(|p| p.is_file())
        .expect("Cargo build script output file must exist");
        fs::read_to_string(&build_output_path)
            .expect("Cargo build script output file must be readable")
    }

    fn find_compiled_build_script_bin(out_dir: &Path) -> Option<PathBuf> {
        let build_root = out_dir.parent()?.parent()?;
        let entries = fs::read_dir(build_root).ok()?;
        for entry in entries.flatten() {
            let dir = entry.path();
            if !dir.is_dir() {
                continue;
            }
            let dir_name = entry.file_name();
            if !dir_name.to_string_lossy().starts_with("math_explorer_gui-") {
                continue;
            }
            for candidate in [
                "build-script-build",
                "build_script_build",
                "build-script-build.exe",
                "build_script_build.exe",
            ] {
                let bin = dir.join(candidate);
                if bin.is_file() {
                    return Some(bin);
                }
            }
        }
        None
    }

    #[test]
    fn test_build_script_emits_scoped_rerun_directives_without_external_crate_sources() {
        let out_dir = Path::new(env!("OUT_DIR"));
        let generated_tabs = fs::read_to_string(out_dir.join("generated_tabs.rs"))
            .expect("OUT_DIR/generated_tabs.rs must be generated by build.rs");
        assert!(
            generated_tabs.contains("pub fn instantiate_tabs()"),
            "generated_tabs.rs should define instantiate_tabs"
        );

        let build_output = read_build_script_output(out_dir);
        let rerun_paths: HashSet<&str> = build_output
            .lines()
            .filter_map(|line| line.strip_prefix("cargo:rerun-if-changed="))
            .collect();

        for path in &rerun_paths {
            assert!(!path.trim().is_empty(), "rerun directive must not be empty");
            assert!(
                !path.contains('\\'),
                "rerun path must use forward slashes: {path}"
            );
            assert!(
                !path.starts_with("../crates/") && !path.starts_with("../math_explorer/"),
                "math_explorer_gui/build.rs must not emit sibling crate rerun path: {path}"
            );
        }

        for expected in [
            "build.rs",
            "build_snapshot.rs",
            "src/tabs",
            "Cargo.toml",
            "../traceability.toml",
            "../papers",
        ] {
            assert!(
                rerun_paths.contains(expected),
                "Missing expected cargo:rerun-if-changed={expected} in math_explorer_gui output"
            );
        }
        if Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../Verification_Certificate.json")
            .exists()
        {
            assert!(rerun_paths.contains("../Verification_Certificate.json"));
        }
        assert!(
            rerun_paths
                .iter()
                .any(|p| p.starts_with("../papers/") && p.ends_with(".tex")),
            "Expected papers/*.tex rerun directives in math_explorer_gui build output"
        );
    }

    #[test]
    fn test_build_script_rerun_preserves_generated_output_mtimes_when_unchanged() {
        let out_dir = Path::new(env!("OUT_DIR"));
        let build_bin = find_compiled_build_script_bin(out_dir)
            .expect("Compiled math_explorer_gui build-script-build binary must exist");
        let manifest_dir = Path::new(env!("CARGO_MANIFEST_DIR"));

        let temp_root = std::env::temp_dir().join(format!(
            "math_explorer_gui_build_mtime_test_{}",
            std::process::id()
        ));
        let _ = fs::remove_dir_all(&temp_root);
        let temp_out = temp_root.join("out");
        let temp_target = temp_root.join("target");
        fs::create_dir_all(&temp_out).unwrap();
        fs::create_dir_all(&temp_target).unwrap();

        let run_once = || {
            let output = Command::new(&build_bin)
                .current_dir(manifest_dir)
                .env("CARGO_MANIFEST_DIR", manifest_dir)
                .env("OUT_DIR", &temp_out)
                .env("CARGO_TARGET_DIR", &temp_target)
                .output()
                .expect("Failed to invoke build-script-build");
            assert!(
                output.status.success(),
                "build-script-build failed: {}",
                String::from_utf8_lossy(&output.stderr)
            );
        };

        run_once();
        let gen_tabs = temp_out.join("generated_tabs.rs");
        let gen_manifest = temp_out.join("traceability_manifest.json");
        let tabs_mtime_before = fs::metadata(&gen_tabs).unwrap().modified().unwrap();
        let manifest_mtime_before = fs::metadata(&gen_manifest).unwrap().modified().unwrap();

        thread::sleep(Duration::from_millis(25));
        run_once();

        assert_eq!(
            fs::metadata(&gen_tabs).unwrap().modified().unwrap(),
            tabs_mtime_before,
            "Unchanged build.rs rerun must preserve generated_tabs.rs mtime"
        );
        assert_eq!(
            fs::metadata(&gen_manifest).unwrap().modified().unwrap(),
            manifest_mtime_before,
            "Unchanged build.rs rerun must preserve traceability_manifest.json mtime"
        );

        let _ = fs::remove_dir_all(&temp_root);
    }
}
